// Linear Search

fun Linear_Search(@init<table> a, key):
    n = length(a)
    for (i = 0; i < n; i += 1):
        if (a[i] == key):
            return i
        end if
    end for
    return -1
end fun

// Binary Search

fun Binary_Search(@init<table> a, key):
    low = 0
    high = length(a) - 1
    while (low <= high):
        mid = floor((low + high) / 2)
        if (a[mid] == key):
            return mid
        else if (a[mid] < key):
            low = mid + 1
        else:
            high = mid - 1
        end if
    end while
    return -1
end fun

// Comparison Counting Sort

fun Comparison_Counting_Sort(@init<table> a):
    n = length(a)
    count = arr(n)
    output = arr(n)
    for (i = 0; i < n - 1; i += 1):
        for (j = i + 1; j < n; j += 1):
            if (a[i] <= a[j]):
                count[j] += 1
            else:
                count[i] += 1
            end if
        end for
    end for
    for (i = 0; i < n; i += 1):
        output[count[i]] = a[i]
    end for
    return output
end fun

