// Check Unique

fun Check_Unique(@init<table> a):
    n = length(a)
    for (i = 0; i < n - 1; i += 1):
        for (j = i + 1; j < n; j += 1):
            if (a[i] == a[j]):
                return 0
            end if
        end for
    end for
    return 1
end fun
